const crypto = require('crypto');

const items = $input.all();
if (items.length === 0) {
  throw new Error('No active approved policies found to build CAG snapshot.');
}

const blocks = items.map(item => {
  const p = item.json;
  const cond = typeof p.conditions === 'object' && p.conditions !== null
    ? JSON.stringify(p.conditions)
    : String(p.conditions || '');
  const validity = `${p.effective_from || ''} - ${p.effective_to ? p.effective_to : 'Süresiz'}`;
  const source = `${p.source_title || 'Sentetik İK Politikası'} / ${p.source_section || 'Genel'} (Sahip: ${p.owner || 'İK'})`;

  return `[POLITIKA_KODU: ${p.policy_code}]
Kategori: ${p.category}
Kanonik Soru: ${p.canonical_question}
Onaylı Cevap: ${p.answer_text}
Koşullar: ${cond}
Geçerlilik: ${validity}
Kaynak: ${source}`;
});

const content = blocks.join('\n\n---\n\n');
const contentHash = crypto.createHash('sha256').update(content, 'utf8').digest('hex');
const tokenEstimate = Math.ceil(content.split(/\s+/).filter(Boolean).length * 1.3);

const sourceVersions = {};
for (const item of items) {
  const p = item.json;
  sourceVersions[p.policy_code] = { version: p.version, category: p.category };
}

return [{
  json: {
    content,
    content_hash: contentHash,
    policy_count: items.length,
    token_estimate: tokenEstimate,
    source_versions_json: JSON.stringify(sourceVersions)
  }
}];

const built = $('Format Compact Context & Hash').first().json;
const activeRows = $input.all();
const active = activeRows.length > 0 && activeRows[0].json.id ? activeRows[0].json : null;

const isIdentical = active && active.content_hash === built.content_hash;
const maxVersion = active ? (active.max_version || active.snapshot_version) : 0;
const nextVersion = isIdentical ? active.snapshot_version : (maxVersion + 1);

return [{
  json: {
    action: isIdentical ? 'SKIPPED' : 'CREATE_NEW',
    should_insert: !isIdentical,
    next_version: nextVersion,
    previous_active_version: active ? active.snapshot_version : null,
    content: built.content,
    content_hash: built.content_hash,
    policy_count: built.policy_count,
    token_estimate: built.token_estimate,
    source_versions_json: built.source_versions_json
  }
}];
